-- Speglar det som lades på databasen 2026-09-15 via apply_migration i fem delar:
--   ley_order_code_from_catalogue_part_01  (backup, schema, familj, parametrar)
--   ley_order_code_from_catalogue_part_02  (värdelista, rensning av regler)
--   ley_order_code_from_catalogue_part_03  (regler 1–20)
--   ley_order_code_from_catalogue_part_04  (regler 21–40)
--   ley_order_code_from_catalogue_part_05  (regler 41–56, dokumentkarta, produktspecar)
-- Fingeravtryck efter körning, identiska med modellen (scripts/fingerprint-rules.ts ley):
--   regler  56   md5 36dc9db86ae8917168c1111c9db91745   villkor fcea67438478391fabff35561d3e5dbc
--   värden  56   md5 32eaaad61c9059c2446cb73a5be9e639
--   schema       md5 97963a940a28d46f195162ab538a86b2
-- Verifierat live: /sv/configurator/ley bygger LEY16B-30-S1 (nyckelns exempel, sida 459),
-- stoppar flänsen G på storlek 32 (not 7) och varnar för mellanslag som specialorder (not 1).
--
-- LEY: beställnyckeln enligt SMC Electric Actuator Rod Type LEY Series (sida 459–460).
-- GENERERAD ur src/lib/catalog/ley.ts -- redigera inte för hand.
--
-- Rättar familjen ley, som hade mallen 'LEY-{size}-{stroke_mm}-{motor_mount}'
-- med fritext (inline/parallel, low/standard/high), storlek 63 (bara AC-servo)
-- och slag 1–1500. SMC:s kod är
-- LEY{storlek}{fäste}{motor}{stigning}-{slag}{motortillval}{stångände}{montering}-{kabel}{styrenhet}{I/O-kabel}{montering}{tillbehör},
-- t.ex. LEY16B-30-S1 (sida 459). Motortyp, lås/kåpa, stångände, fästen, kabel och
-- styrenhet (JXC/LEC, en nyckel i nyckeln, gemensam med LESH) fanns inte alls.
--
-- SMC-LEY får katalogens slag, tryckkraft, repeternoggrannhet och motorer.

begin;

create schema if not exists backup;
create table if not exists backup.ley_before_20260915 as
  select 'param' as sort, p.id::text as id, p.param_key as k, p.label as v
  from configurator_params p join configurator_families f on f.id = p.family_id
  where f.slug = 'ley'
  union all
  select 'value', v.id::text, v.code, v.label
  from configurator_param_values v
  join configurator_params p on p.id = v.param_id
  join configurator_families f on f.id = p.family_id
  where f.slug = 'ley'
  union all
  select 'family', f.id::text, f.slug, coalesce(f.order_code_template, '')
  from configurator_families f where f.slug = 'ley';

insert into config_schemas (schema_id, schema_json, title_sv, title_en, category_slug)
values ('SCHEMA-LEY-V1', '{"version":"1.0","steps":[{"id":"size","step":1,"title_sv":"Storlek","title_en":"Size","required":true,"type":"single_select","options":[{"v":"16","label":"Storlek 16 (motor 28, slag 30–300)"},{"v":"25","label":"Storlek 25 (motor 42, slag 30–400)"},{"v":"32","label":"Storlek 32 (motor 56,4, slag 30–500)"},{"v":"40","label":"Storlek 40 (motor 56,4, slag 30–500)"}]},{"id":"mount","step":2,"title_sv":"Motorns placering (standard är parallellt på ovansidan)","title_en":"Motor mounting position (top side parallel is standard)","required":false,"type":"single_select","options":[{"v":"R","label":"Motorn parallellt på höger sida (R; standard är ovansidan)"},{"v":"L","label":"Motorn parallellt på vänster sida (L)"},{"v":"D","label":"Motorn i linje bakom cylindern (D)"}]},{"id":"motor","step":3,"title_sv":"Motortyp (standard är stegmotor 24 V DC)","title_en":"Motor type (step motor 24 VDC is standard)","required":false,"type":"single_select","options":[{"v":"A","label":"Servomotor 24 V DC, inkrementell (storlek 16 och 25; styrenhet LECA6)"}]},{"id":"lead","step":4,"title_sv":"Stigning","title_en":"Lead","required":true,"type":"single_select","options":[{"v":"A","label":"Hög stigning: 10/12/16/16 mm för storlek 16/25/32/40"},{"v":"B","label":"Mellanstigning: 5/6/8/8 mm"},{"v":"C","label":"Låg stigning: 2,5/3/4/4 mm"}]},{"id":"stroke_mm","step":5,"title_sv":"Slaglängd","title_en":"Stroke","required":true,"type":"numeric","min":10,"max":500,"unit":"mm"},{"id":"motor_opt","step":6,"title_sv":"Motortillval","title_en":"Motor option","required":false,"type":"single_select","options":[{"v":"C","label":"Med motorkåpa"},{"v":"B","label":"Med lås (omagnetiserande)"},{"v":"W","label":"Med lås och motorkåpa"}]},{"id":"rod_end","step":7,"title_sv":"Kolvstångsände","title_en":"Rod end thread","required":false,"type":"single_select","options":[{"v":"M","label":"Hangängad kolvstångsände (en stångändmutter medföljer; standard är hongänga)"}]},{"id":"mounting","step":8,"title_sv":"Fäste (standard är gängade ändar och gängad botten)","title_en":"Mounting (ends tapped/body bottom tapped is standard)","required":false,"type":"single_select","options":[{"v":"L","label":"Fotfäste (bara motorn parallellt)"},{"v":"F","label":"Fläns vid kolvstången (bara motorn parallellt)"},{"v":"G","label":"Fläns vid gaveln (bara motorn parallellt, storlek 16 och 25)"},{"v":"D","label":"Dubbelt gaffelfäste (bara motorn parallellt)"}]},{"id":"cable","step":9,"title_sv":"Aktuatorkabel","title_en":"Actuator cable type/length","required":false,"type":"single_select","options":[{"v":"S1","label":"Standardkabel 1,5 m (bara stegmotor, fast förlagd)"},{"v":"S3","label":"Standardkabel 3 m (bara stegmotor, fast förlagd)"},{"v":"S5","label":"Standardkabel 5 m (bara stegmotor, fast förlagd)"},{"v":"R1","label":"Robotkabel 1,5 m"},{"v":"R3","label":"Robotkabel 3 m"},{"v":"R5","label":"Robotkabel 5 m"},{"v":"R8","label":"Robotkabel 8 m (på beställning)"},{"v":"RA","label":"Robotkabel 10 m (på beställning)"},{"v":"RB","label":"Robotkabel 15 m (på beställning)"},{"v":"RC","label":"Robotkabel 20 m (på beställning)"}]},{"id":"ctrl","step":10,"title_sv":"Styrenhet (aktuator och styrenhet säljs som ett paket)","title_en":"Controller (actuator and controller are sold as a package)","required":false,"type":"single_select","options":[{"v":"C51","label":"JXC51: parallell I/O NPN, stegdata"},{"v":"C61","label":"JXC61: parallell I/O PNP, stegdata"},{"v":"CE1","label":"JXCE1: EtherCAT"},{"v":"CEF","label":"JXCEF: EtherCAT med STO"},{"v":"C91","label":"JXC91: EtherNet/IP"},{"v":"C9F","label":"JXC9F: EtherNet/IP med STO"},{"v":"CP1","label":"JXCP1: PROFINET"},{"v":"CPF","label":"JXCPF: PROFINET med STO"},{"v":"CD1","label":"JXCD1: DeviceNet"},{"v":"CL1","label":"JXCL1: IO-Link"},{"v":"CLF","label":"JXCLF: IO-Link med STO"},{"v":"CM1","label":"JXCM1: CC-Link"},{"v":"6N","label":"LECA6 NPN: stegdata, för servomotorn"},{"v":"6P","label":"LECA6 PNP: stegdata, för servomotorn"},{"v":"AN","label":"LECPA NPN: pulsingång, för stegmotorn (inkrementell)"},{"v":"AP","label":"LECPA PNP: pulsingång, för stegmotorn (inkrementell)"}]},{"id":"io_cable","step":11,"title_sv":"I/O-kabel (LEC)","title_en":"I/O cable (LEC)","required":false,"type":"single_select","options":[{"v":"1","label":"I/O-kabel 1,5 m (LEC)"},{"v":"3","label":"I/O-kabel 3 m (LEC)"},{"v":"5","label":"I/O-kabel 5 m (LEC)"}]},{"id":"ctrl_mount","step":12,"title_sv":"Styrenhetens montering","title_en":"Controller mounting","required":false,"type":"single_select","options":[{"v":"7","label":"Skruvmontering (JXC)"},{"v":"8","label":"DIN-skena (JXC; skenan beställs separat)"},{"v":"D","label":"DIN-skena (LEC; skenan beställs separat)"}]},{"id":"ctrl_acc","step":13,"title_sv":"Styrenhetens tillbehör (JXC)","title_en":"Controller accessory (JXC)","required":false,"type":"single_select","options":[{"v":"S","label":"Rak kommunikationsplugg (DeviceNet, CC-Link)"},{"v":"T","label":"T-grenad kommunikationsplugg (DeviceNet, CC-Link)"},{"v":"1","label":"I/O-kabel 1,5 m (JXC51/61)"},{"v":"3","label":"I/O-kabel 3 m (JXC51/61)"},{"v":"5","label":"I/O-kabel 5 m (JXC51/61)"}]}]}'::jsonb,
        'SMC LEY elektrisk stångcylinder 24 V DC', 'SMC LEY electric rod actuator 24 VDC', 'electric-actuator')
on conflict (schema_id) do update set
  schema_json = excluded.schema_json,
  title_sv = excluded.title_sv,
  title_en = excluded.title_en;

update configurator_families set
  title = 'Elektrisk stångcylinder, storlek 16–40, stegmotor eller servomotor 24 V DC, med styrenhet',
  description = 'SMC LEY electric rod actuator (ball screw): sizes 16, 25, 32 and 40, step motor or servo motor 24 VDC, strokes 30–500 mm, lock/motor cover, foot/flange/clevis mountings, JXC or LEC controller in the same part number.',
  stroke_min_mm = 10,
  stroke_max_mm = 500,
  order_code_template = 'LEY{size}{mount}{motor}{lead}-{stroke_mm}{motor_opt}{rod_end}{mounting}-{cable}{ctrl}{io_cable}{ctrl_mount}{ctrl_acc}',
  rules_schema_id = 'SCHEMA-LEY-V1'
where slug = 'ley';


delete from configurator_param_values v using configurator_params p, configurator_families f
  where v.param_id = p.id and p.family_id = f.id and f.slug = 'ley';
delete from configurator_params p using configurator_families f
  where p.family_id = f.id and f.slug = 'ley';

