     jsonb_to_recordset('[{"param_key":"size","label":"Storlek","param_type":"select","sort_order":1,"required":true,"min_value":null,"max_value":null},{"param_key":"mount","label":"Motorns placering (standard är parallellt på ovansidan)","param_type":"select","sort_order":2,"required":false,"min_value":null,"max_value":null},{"param_key":"motor","label":"Motortyp (standard är stegmotor 24 V DC)","param_type":"select","sort_order":3,"required":false,"min_value":null,"max_value":null},{"param_key":"lead","label":"Stigning","param_type":"select","sort_order":4,"required":true,"min_value":null,"max_value":null},{"param_key":"stroke_mm","label":"Slaglängd","param_type":"number","sort_order":5,"required":true,"min_value":10,"max_value":500},{"param_key":"motor_opt","label":"Motortillval","param_type":"select","sort_order":6,"required":false,"min_value":null,"max_value":null},{"param_key":"rod_end","label":"Kolvstångsände","param_type":"select","sort_order":7,"required":false,"min_value":null,"max_value":null},{"param_key":"mounting","label":"Fäste (standard är gängade ändar och gängad botten)","param_type":"select","sort_order":8,"required":false,"min_value":null,"max_value":null},{"param_key":"cable","label":"Aktuatorkabel","param_type":"select","sort_order":9,"required":false,"min_value":null,"max_value":null},{"param_key":"ctrl","label":"Styrenhet (aktuator och styrenhet säljs som ett paket)","param_type":"select","sort_order":10,"required":false,"min_value":null,"max_value":null},{"param_key":"io_cable","label":"I/O-kabel (LEC)","param_type":"select","sort_order":11,"required":false,"min_value":null,"max_value":null},{"param_key":"ctrl_mount","label":"Styrenhetens montering","param_type":"select","sort_order":12,"required":false,"min_value":null,"max_value":null},{"param_key":"ctrl_acc","label":"Styrenhetens tillbehör (JXC)","param_type":"select","sort_order":13,"required":false,"min_value":null,"max_value":null}]'::jsonb)
       as r(param_key text, label text, param_type text, sort_order int, required boolean,
