join configurator_params p on p.param_key = r.param_key
join configurator_families f on f.id = p.family_id and f.slug = 'ley';

delete from config_rules where schema_id = 'SCHEMA-LEY-V1';


insert into config_rules (schema_id, severity, if_json, message_sv, message_en, goto_step)
select 'SCHEMA-LEY-V1', r->>'severity', r->'if_json',
       r->>'message_sv', r->>'message_en', r->>'goto_step'
from jsonb_array_elements('[{"severity":"error","if_json":{"and":[{"==":[{"var":"motor"},"A"]},{"in":[{"var":"size"},["32","40"]]}]},"message_sv":"Servomotorn A finns i storlek 16 och 25, inte 32 och 40 (sida 459).","message_en":"The servo motor A exists in size 16 and 25, not 32 and 40 (page 459).","goto_step":"ley-motor"},{"severity":"error","if_json":{"and":[{"==":[{"var":"size"},"16"]},{">":[{"var":"stroke_mm"},0]},{"or":[{"<":[{"var":"stroke_mm"},10]},{">":[{"var":"stroke_mm"},300]}]}]},"message_sv":"Storlek 16 tillverkas med 10–300 mm slag (sida 459).","message_en":"Size 16 is manufactured with 10–300 mm stroke (page 459).","goto_step":"ley-stroke_mm"},{"severity":"warn","if_json":{"and":[{"==":[{"var":"size"},"16"]},{">=":[{"var":"stroke_mm"},10]},{"<=":[{"var":"stroke_mm"},300]},{"not":{"in":[{"var":"stroke_mm"},[30,50,100,150,200,250,300]]}}]},"message_sv":"Standardslagen för storlek 16 är 30, 50, 100, 150, 200, 250 och 300 mm; andra slag tillverkas som specialorder — kontakta SMC (sida 459–460, not 1).","message_en":"The standard strokes for size 16 are 30, 50, 100, 150, 200, 250 and 300 mm; other strokes are produced as special orders — contact SMC (pages 459–460, note 1).","goto_step":"ley-stroke_mm"},{"severity":"error","if_json":{"and":[{"==":[{"var":"size"},"25"]},{">":[{"var":"stroke_mm"},0]},{"or":[{"<":[{"var":"stroke_mm"},15]},{">":[{"var":"stroke_mm"},400]}]}]},"message_sv":"Storlek 25 tillverkas med 15–400 mm slag (sida 459).","message_en":"Size 25 is manufactured with 15–400 mm stroke (page 459).","goto_step":"ley-stroke_mm"},{"severity":"warn","if_json":{"and":[{"==":[{"var":"size"},"25"]},{">=":[{"var":"stroke_mm"},15]},{"<=":[{"var":"stroke_mm"},400]},{"not":{"in":[{"var":"stroke_mm"},[30,50,100,150,200,250,300,350,400]]}}]},"message_sv":"Standardslagen för storlek 25 är 30, 50, 100, 150, 200, 250, 300, 350 och 400 mm; andra slag tillverkas som specialorder — kontakta SMC (sida 459–460, not 1).","message_en":"The standard strokes for size 25 are 30, 50, 100, 150, 200, 250, 300, 350 and 400 mm; other strokes are produced as special orders — contact SMC (pages 459–460, note 1).","goto_step":"ley-stroke_mm"},{"severity":"error","if_json":{"and":[{"==":[{"var":"size"},"32"]},{">":[{"var":"stroke_mm"},0]},{"or":[{"<":[{"var":"stroke_mm"},20]},{">":[{"var":"stroke_mm"},500]}]}]},"message_sv":"Storlek 32 tillverkas med 20–500 mm slag (sida 459).","message_en":"Size 32 is manufactured with 20–500 mm stroke (page 459).","goto_step":"ley-stroke_mm"},{"severity":"warn","if_json":{"and":[{"==":[{"var":"size"},"32"]},{">=":[{"var":"stroke_mm"},20]},{"<=":[{"var":"stroke_mm"},500]},{"not":{"in":[{"var":"stroke_mm"},[30,50,100,150,200,250,300,350,400,450,500]]}}]},"message_sv":"Standardslagen för storlek 32 är 30, 50, 100, 150, 200, 250, 300, 350, 400, 450 och 500 mm; andra slag tillverkas som specialorder — kontakta SMC (sida 459–460, not 1).","message_en":"The standard strokes for size 32 are 30, 50, 100, 150, 200, 250, 300, 350, 400, 450 and 500 mm; other strokes are produced as special orders — contact SMC (pages 459–460, note 1).","goto_step":"ley-stroke_mm"},{"severity":"error","if_json":{"and":[{"==":[{"var":"size"},"40"]},{">":[{"var":"stroke_mm"},0]},{"or":[{"<":[{"var":"stroke_mm"},20]},{">":[{"var":"stroke_mm"},500]}]}]},"message_sv":"Storlek 40 tillverkas med 20–500 mm slag (sida 459).","message_en":"Size 40 is manufactured with 20–500 mm stroke (page 459).","goto_step":"ley-stroke_mm"},{"severity":"warn","if_json":{"and":[{"==":[{"var":"size"},"40"]},{">=":[{"var":"stroke_mm"},20]},{"<=":[{"var":"stroke_mm"},500]},{"not":{"in":[{"var":"stroke_mm"},[30,50,100,150,200,250,300,350,400,450,500]]}}]},"message_sv":"Standardslagen för storlek 40 är 30, 50, 100, 150, 200, 250, 300, 350, 400, 450 och 500 mm; andra slag tillverkas som specialorder — kontakta SMC (sida 459–460, not 1).","message_en":"The standard strokes for size 40 are 30, 50, 100, 150, 200, 250, 300, 350, 400, 450 and 500 mm; other strokes are produced as special orders — contact SMC (pages 459–460, note 1).","goto_step":"ley-stroke_mm"},{"severity":"warn","if_json":{"and":[{"in":[{"var":"motor_opt"},["B","W"]]},{"!=":[{"var":"mount"},"D"]},{"in":[{"var":"size"},["16","40"]]},{">":[{"var":"stroke_mm"},0]},{"<=":[{"var":"stroke_mm"},30]}]},"message_sv":"Med lås (B/W) och motorn parallellt sticker motorkroppen ut bakom cylindern i storlek 16 och 40 vid slag upp till 30 mm — kontrollera att den inte kolliderar (sida 460, not 2).","message_en":"With the lock (B/W) and the motor mounted in parallel the motor body sticks out behind the cylinder in sizes 16 and 40 at strokes up to 30 mm — check for interference (page 460, note 2).","goto_step":"ley-motor_opt"},{"severity":"error","if_json":{"and":[{"==":[{"var":"mount"},"D"]},{"in":[{"var":"mounting"},["L","F","G","D"]]}]},"message_sv":"Fästena L, F, G och D finns bara med motorn parallellt, inte i linje D (sida 459).","message_en":"The mountings L, F, G and D exist only with the motor in parallel, not in-line D (page 459).","goto_step":"ley-mounting"},{"severity":"error","if_json":{"and":[{"==":[{"var":"mounting"},"G"]},{"in":[{"var":"size"},["32","40"]]}]},"message_sv":"Flänsen vid gaveln G finns inte för storlek 32 och 40 (sida 460, not 7).","message_en":"The head flange G is not available for size 32 and 40 (page 460, note 7).","goto_step":"ley-mounting"},{"severity":"error","if_json":{"and":[{"==":[{"var":"mounting"},"F"]},{"in":[{"var":"motor_opt"},["B","W"]]},{"in":[{"var":"size"},["16","40"]]},{"==":[{"var":"stroke_mm"},30]}]},"message_sv":"Flänsen vid kolvstången F finns inte för storlek 16 och 40 med 30 mm slag och lås (B/W) (sida 460, not 6).","message_en":"The rod flange F is not available for sizes 16 and 40 with a 30 mm stroke and the lock (B/W) (page 460, note 6).","goto_step":"ley-mounting"},{"severity":"error","if_json":{"and":[{"==":[{"var":"mounting"},"D"]},{"in":[{"var":"size"},["16"]]},{">":[{"var":"stroke_mm"},100]}]},"message_sv":"Det dubbla